import {decompressLZ,decodeText} from './rom.js';
import {discoverEmeraldRegion,discoverFireRedRegion} from './region-discovery.js';
import {STOCK_FIRE_RED_SHA} from './verified-frlg.js';
import {encodedText} from './item-maker.js';
const BASE=0x08000000;
// Stock English FireRed 1.0. Resource labels/layout cross-checked against
// pret/pokefirered src/region_map.c and HMA's BPRE0 metadata.
const PROFILE={palette:0x3ef2dc,tiles:0x3ef61c,pages:[0x3f089c,0x3f0afc,0x3f0c0c,0x3f0cf0],names:0x3f1cac,xy:0x3f1e60,wh:0x3f2178,count:109};
export function regionProfile(hash){if(hash==='a9dec84dfe7f62ab2220bafaef7479da0929d066ece16a6885f6226db19085af')return{engine:'emerald',label:'English Emerald',palette:0x59f73c,tiles:0x59f77c,tilemap:0x5a04e0,entries:0x5a147c,count:213};if(hash===STOCK_FIRE_RED_SHA)return{...PROFILE,label:'English FireRed 1.0'};throw Error('The opened ROM’s world-map resource layout needs a compatible adapter. Map editing, settlement generation and ROM dialogue remain available.');}
export const REGION_PAGES=['Kanto','Sevii 1–3','Sevii 4–5','Sevii 6–7'];
const integer=(v,min,max)=>Number.isInteger(v)&&v>=min&&v<=max;
export function validateRegionEdits(edits){if(edits===undefined)return;if(!edits||Array.isArray(edits)||Object.keys(edits).length>16)throw Error('Invalid world-map edits.');for(const [hash,e] of Object.entries(edits)){if(!/^[a-f0-9]{64}$/.test(hash)||!e||!e.pages||!e.locations)throw Error('Invalid world-map source.');for(const [page,cells]of Object.entries(e.pages)){if(!/^[0-3]$/.test(page)||!Array.isArray(cells)||![600,1024].includes(cells.length)||cells.some(n=>!integer(n,0,65535)))throw Error('Invalid Town Map tile page.');}for(const[id,row]of Object.entries(e.locations)){if(!/^\d+$/.test(id)||!integer(+id,0,255)||!row||typeof row.name!=='string'||!row.name.trim()||row.name.length>40||!integer(row.x,0,29)||!integer(row.y,0,19)||!integer(row.width,0,30)||!integer(row.height,0,20)||((!row.width||!row.height)&&!(row.width===0&&row.height===0&&row.x===0&&row.y===0))||row.x+row.width>30||row.y+row.height>20)throw Error('Invalid Town Map location bounds.');encodedText(row.name);}}}
export function readRegionMap(reader,hash){let p;try{p=regionProfile(hash);}catch(e){p=discoverFireRedRegion(reader)||discoverEmeraldRegion(reader);if(!p)throw e;}if(p.engine==='emerald')return readEmeraldRegion(reader,p);const b=reader.bytes,v=new DataView(b.buffer,b.byteOffset,b.byteLength);if(p.wh+p.count*4>b.length)throw Error('Town Map tables are missing.');const tiles=decompressLZ(b,p.tiles,32768);if(tiles.length%32||tiles.length<32)throw Error('Invalid Town Map tileset.');const palettes=Array.from({length:80},(_,i)=>{const n=v.getUint16(p.palette+i*2,true);if(n&32768)throw Error('Invalid Town Map palette.');return[(n&31)*255/31,(n>>5&31)*255/31,(n>>10&31)*255/31];});const pages=p.pages.map(at=>{const raw=decompressLZ(b,at,4096);if(raw.length!==1200)throw Error('Unexpected Town Map dimensions.');const w=new DataView(raw.buffer,raw.byteOffset,raw.byteLength);return Array.from({length:600},(_,i)=>w.getUint16(i*2,true));});for(const cells of pages)for(const word of cells)if((word&1023)>=tiles.length/32||(word>>>12)>=5)throw Error('Town Map references unsupported graphics.');const locations=Array.from({length:p.count},(_,i)=>{const ptr=v.getUint32(p.names+i*4,true)-BASE,name=decodeText(b,ptr,80);if(ptr<512||!name)throw Error('Invalid Town Map name table.');return{id:i,name,x:v.getUint16(p.xy+i*4,true),y:v.getUint16(p.xy+i*4+2,true),width:v.getUint16(p.wh+i*4,true),height:v.getUint16(p.wh+i*4+2,true)};});return{tiles,palettes,pages,locations,profile:p};}
// Literal-only GBA LZ77 stream. Keeps compression bounded and deterministic.
export function regionLZ(raw){const out=[16,raw.length&255,raw.length>>8&255,raw.length>>16&255];for(let i=0;i<raw.length;i+=8)out.push(0,...raw.slice(i,i+8));while(out.length%4)out.push(0);return Uint8Array.from(out);}
export function installRegionMap(project,reader,hash,output){const e=project.regionMaps?.[hash];if(!e)return[];validateRegionEdits({[hash]:e});const native=readRegionMap(reader,hash),p=native.profile,reports=[];if(p.engine==='emerald')return installEmeraldRegion(e,reader,native,output);if(Object.values(e.pages).some(c=>c.length!==600)||Object.keys(e.locations).some(id=>+id>=p.count))throw Error('Town Map edits do not match this source layout.');const v=new DataView(reader.bytes.buffer,reader.bytes.byteOffset,reader.bytes.byteLength);for(const [page,cells]of Object.entries(e.pages)){if(cells.some(w=>(w&1023)>=native.tiles.length/32||(w>>>12)>=5))throw Error('Town Map tile is outside its source tileset.');if(cells.every((w,i)=>w===native.pages[page][i]))continue;const refs=[];for(let at=512;at+4<=reader.bytes.length;at+=4)if(v.getUint32(at,true)===BASE+p.pages[page])refs.push(at);if(!refs.length||refs.length>32)throw Error('Town Map page references failed verification.');const raw=new Uint8Array(1200),w=new DataView(raw.buffer);cells.forEach((n,i)=>w.setUint16(i*2,n,true));const to=output.allocate(regionLZ(raw),'Town Map '+REGION_PAGES[page]);for(const ref of refs)output.int(ref,BASE+to);reports.push('Town Map '+REGION_PAGES[page]+': native artwork updated');}for(const[id,row]of Object.entries(e.locations)){const i=+id,old=native.locations[i];if((!row.width||!row.height)&&(old.width||old.height))throw Error('Keep positive dimensions for a placed Town Map location.');if(row.name!==old.name)output.int(p.names+i*4,BASE+output.allocate(encodedText(row.name),'Town Map name'));for(const [base,a,c]of [[p.xy,row.x,row.y],[p.wh,row.width,row.height]]){output.int(base+i*4,a,2);output.int(base+i*4+2,c,2);}reports.push('Town Map location: '+row.name+' · name and player-marker bounds');}return reports;}
export function regionPixels(native,cells,out=null){const width=native.width||30,height=native.height||20;out??=new Uint8ClampedArray(width*height*64*4);if(out.length!==width*height*64*4||cells.length!==width*height)throw Error('Invalid Town Map pixel buffer.');for(let cell=0;cell<cells.length;cell++){const w=cells[cell],tile=w&1023,bank=native.bpp===8?0:w>>>12;for(let y=0;y<8;y++)for(let x=0;x<8;x++){const sx=w&1024?7-x:x,sy=w&2048?7-y:y,n=sy*8+sx,b=native.tiles[tile*(native.bpp===8?64:32)+(native.bpp===8?n:n>>1)],index=native.bpp===8?b:bank*16+(n%2?b>>4:b&15),color=native.palettes[index]||[0,0,0],at=((Math.floor(cell/width)*8+y)*width*8+cell%width*8+x)*4;out[at]=color[0];out[at+1]=color[1];out[at+2]=color[2];out[at+3]=255;}}return out;}
function readEmeraldRegion(reader,p){const b=reader.bytes,v=new DataView(b.buffer,b.byteOffset,b.byteLength),tiles=decompressLZ(b,p.tiles,32768),raw=decompressLZ(b,p.tilemap,8192);if(tiles.length!==233*64||raw.length!==4096)throw Error('Emerald world-map graphics failed verification.');const palettes=Array.from({length:256},()=>[0,0,0]);for(let i=0;i<32;i++){const n=v.getUint16(p.palette+i*2,true);if(n&32768)throw Error('Emerald world-map palette failed verification.');palettes[112+i]=[(n&31)*255/31,(n>>5&31)*255/31,(n>>10&31)*255/31];}if(tiles.some(n=>n<112||n>=144))throw Error('Emerald world-map pixels exceed the verified palette.');const pages=[0,1,2,3].map(page=>Array.from({length:1024},(_,i)=>raw[(Math.floor(page/2)*32+Math.floor(i/32))*64+(page%2)*32+i%32]));if(pages.flat().some(n=>n>=233))throw Error('Emerald world-map tile references failed verification.');const locations=Array.from({length:p.count},(_,id)=>{const at=p.entries+id*8,ptr=v.getUint32(at+4,true)-BASE;if((ptr<512||ptr>=b.length)&&v.getUint32(at+4,true)!==0)throw Error('Emerald world-map name table failed verification.');return{id,name:ptr<512?'Location '+id:decodeText(b,ptr,80)||'Location '+id,x:b[at],y:b[at+1],width:b[at+2],height:b[at+3]};});return{profile:p,tiles,palettes,pages,locations,width:32,height:32,bpp:8,paletteBanks:1,pageNames:['Hoenn · top left','Hoenn · top right','Hoenn · bottom left','Hoenn · bottom right']};}
function installEmeraldRegion(e,reader,native,output){const p=native.profile,reports=[];if(Object.values(e.pages).some(c=>c.length!==1024)||Object.keys(e.locations).some(id=>+id>=p.count))throw Error('Emerald world-map edits do not match this source layout.');if(Object.keys(e.pages).length){const raw=new Uint8Array(4096),v=new DataView(raw.buffer);for(let page=0;page<4;page++){const cells=e.pages[page]||native.pages[page];if(cells.some(n=>n>=233))throw Error('Emerald world-map tile is outside its source graphics.');cells.forEach((n,i)=>raw[(Math.floor(page/2)*32+Math.floor(i/32))*64+(page%2)*32+i%32]=n);}const refs=[],source=new DataView(reader.bytes.buffer,reader.bytes.byteOffset,reader.bytes.byteLength);for(let at=512;at+4<=reader.bytes.length;at+=4)if(source.getUint32(at,true)===BASE+p.tilemap)refs.push(at);if(!refs.length||refs.length>16)throw Error('Emerald world-map references failed verification.');const to=output.allocate(regionLZ(raw),'Emerald world-map artwork');for(const ref of refs)output.int(ref,BASE+to);reports.push('Emerald Town Map: native 8-bit artwork updated');}for(const [id,row]of Object.entries(e.locations)){if(row.x+row.width>28||row.y+row.height>15)throw Error('Emerald player-marker bounds must fit its 28 × 15 location grid.');const at=p.entries+Number(id)*8;if(row.name!==native.locations[id].name)output.int(at+4,BASE+output.allocate(encodedText(row.name),'Emerald location name'));output.write(at,Uint8Array.of(row.x,row.y,row.width,row.height));reports.push('Emerald location: '+row.name);}return reports;}
